package vn.com.apartment.commercial;import java.util.List;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface CommercialServiceAssignmentRepository extends JpaRepository<CommercialServiceAssignment,Long>{@Query("select a from CommercialServiceAssignment a join fetch a.space s join fetch s.building order by s.code,a.serviceName")List<CommercialServiceAssignment> findAllDetailed();@Query("select a from CommercialServiceAssignment a where a.space.id=:spaceId and a.active=true order by a.id")List<CommercialServiceAssignment> findActiveForSpace(@Param("spaceId")Long spaceId);}
